 create schema storage; create table storage.objects(bucket_id text,name text,metadata jsonb,updated_at timestamptz default now(),primary key(bucket_id,name));
create table public.live_events (id uuid default gen_random_uuid(),slug text check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text),name text,location text,event_date date,start_time_label text,distance_label text,status text default 'setup'::text check (status = ANY (ARRAY['setup'::text, 'shadow'::text, 'live'::text, 'finished'::text, 'official'::text, 'archived'::text])),is_public boolean default false,current_revision bigint default 0 check (current_revision >= 0),last_published_at timestamp with time zone,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now());
create table public.result_snapshots (id uuid default gen_random_uuid(),event_id uuid,revision bigint check (revision > 0),source_updated_at timestamp with time zone,received_at timestamp with time zone default now(),result_count integer check (result_count >= 0),checksum text,payload jsonb);
create table public.event_settings (event_id uuid,timezone text default 'America/New_York'::text,show_gun_time boolean default true,show_chip_time boolean default true,show_pace boolean default true,awards jsonb default '{"age_groups": [], "overall_places": 3, "special_divisions": [], "remove_overall_from_age_groups": true}'::jsonb check (jsonb_typeof(awards) = 'object'::text),created_at timestamp with time zone default now(),updated_at timestamp with time zone default now(),event_logo_path text,event_logo_alt text,accent_color text default '#b30f2b'::text check (accent_color ~ '^#[0-9A-Fa-f]{6}$'::text),show_overall_place boolean default true,show_bib boolean default true,show_name boolean default true,show_gender boolean default true,show_age boolean default false,show_age_group boolean default true,show_team boolean default false,show_recent_finishers boolean default true,recent_finishers_default_count integer default 10 check (recent_finishers_default_count = ANY (ARRAY[5, 10, 15, 20])),team_scoring jsonb default '{"enabled": false, "tiebreaker": "ncaa_head_to_head", "division_mode": "all", "unattached_mode": "skip_compress", "scorers_per_team": 5, "displacers_per_team": 2}'::jsonb check (jsonb_typeof(team_scoring) = 'object'::text),featured_race_key text);
create table public.finisher_events (id bigint,event_id uuid,bib text,detected_revision bigint check (detected_revision > 0),detected_at timestamp with time zone,created_at timestamp with time zone default now(),race text default ''::text);
create table public.bridge_event_grants (bridge_client_id uuid,event_id uuid,can_read boolean default true,can_publish boolean default false,active boolean default true,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now(),require_lease boolean default false);
create table public.event_race_aliases (id bigint,event_id uuid,source_label text check (btrim(source_label) <> ''::text),race_key text check (race_key ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text),display_label text check (btrim(display_label) <> ''::text),sort_order integer default 0,active boolean default true,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now(),running_clock_enabled boolean default false,running_clock_start_at timestamp with time zone,running_clock_source text check (running_clock_source IS NULL OR (running_clock_source = ANY (ARRAY['manual'::text, 'admin_now'::text, 'push'::text, 'mylaps'::text]))),scheduled_start_time time without time zone);
create table public.bridge_writer_leases (event_id uuid,bridge_client_id uuid,lease_token_hash text check (lease_token_hash ~ '^[0-9a-f]{64}$'::text),acquired_at timestamp with time zone default now(),last_renewed_at timestamp with time zone default now(),expires_at timestamp with time zone);
create table public.bridge_event_policies (event_id uuid,require_lease boolean default false,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now());
create table public.admin_clients(id uuid primary key,active boolean);
create table public.admin_sessions(id uuid default gen_random_uuid() primary key,admin_client_id uuid references public.admin_clients(id),token_hash text unique,expires_at timestamptz);
create table public.event_admin_activity(id bigint generated always as identity primary key,event_id uuid,action text,detail jsonb,created_at timestamptz default now());
alter table public.live_events add primary key(id);
alter table public.live_events add unique(slug);
alter table public.event_settings add primary key(event_id);
alter table public.event_settings add foreign key(event_id) references public.live_events(id);
alter table public.event_race_aliases alter column id set not null;
alter table public.event_race_aliases alter column id add generated by default as identity;
alter table public.event_race_aliases add unique(event_id,race_key);
alter table public.event_race_aliases add unique(event_id,source_label);
grant usage on schema public,storage to service_role;
grant all on all tables in schema public,storage to service_role;
grant usage,select on all sequences in schema public to service_role;

grant usage on schema public to anon,authenticated;

alter table event_settings add column show_entry_list boolean default false, add column show_podium boolean default true, add column show_grade boolean default false, add column grade_source text default 'category', add column podium_mode text default 'featured', add column podium_configs jsonb default '[]', add column course_records jsonb default '[]';
